import sys,json,uuid,copy,os
from pathlib import Path
root=Path(__file__).resolve().parent/'commentary-regression-novel'
sys.path.insert(0,str(root/'.novel-creator/src'))
from novel_creator import records,storage
assert not os.environ.get('PYTHONPATH')
assert Path(records.__file__).resolve().is_relative_to(root)
e=root/'.novel-creator/local/evidence'
def ref(r):return {'id':r['id'],'revision':r['revision']}
def cite(r):return r['id'][:8]+' r'+str(r['revision'])
def timing():
 a={'precision':'unknown','event_anchor':None,'start':None,'end':None,'before_refs':[],'after_refs':[]}
 return {'chronology':copy.deepcopy(a),'narrative':copy.deepcopy(a)}
class Turn:
 def __init__(self,case):
  self.case=case;self.capture=json.loads((e/(case+'-capture.json')).read_text(encoding='utf-8-sig'));assert self.capture['ok'];self.text=self.capture['data']['text'];self.history=storage.read_history(root);self.before=records.fold(self.history)
  self.p=records.new_exchange(self.history[-1]['novel_id'],previous=self.history[-1],expected_head=storage.head(root),messages=[{'message_id':str(uuid.uuid4()),'role':'user','text':self.text},{'message_id':str(uuid.uuid4()),'role':'assistant','text':''}]);self.p['input_artifacts']=[self.capture['data']['input_artifact']];self.rs=self.p['record_versions']
 def src(self,fragment):
  start=self.text.index(fragment);assert self.text[start:start+len(fragment)]==fragment
  return dict(records.current_user_source(self.p),range={'start':start,'end':start+len(fragment)})
 def base(self,kind,fragment):return {'id':str(uuid.uuid4()),'kind':kind,'revision':1,'previous_revision':None,'source_refs':[self.src(fragment)],'created_exchange_id':self.p['exchange_id'],'origin':'supplied'}
 def add(self,r):self.rs.append(r);return r
 def revise(self,r,fragment):
  x=copy.deepcopy(r);x.update(revision=r['revision']+1,previous_revision=r['revision'],source_refs=r['source_refs']+[self.src(fragment)],origin='supplied');return self.add(x)
 def decision(self,action,fragment,targets,results,parts,reason,prior=None):
  d=self.base('decision',fragment);d.update(action=action,user_message_ref=self.src(fragment),span=self.src(fragment)['range'],target_refs=[ref(x) for x in targets],selected_parts=parts,prior_refs=[ref(x) for x in (prior or [])],result_refs=[ref(x) for x in results],reason=reason,affected_refs=[ref(x) for x in results],review_required_refs=[]);return self.add(d)
 def assertion(self,subject,predicate,value,fragment,status='proposed',truth='affirmed'):
  a=self.base('assertion',fragment);a.update(subject_element_id=subject['id'],predicate=predicate,value=value,perspective='author_truth',holder_id=None,reader_audience=None,time_ref=timing(),truth_state=truth,status=status,decision_ids=[],supersedes=None);return self.add(a)
 def idea(self,statement,fragment,elements,status='proposed'):
  i=self.base('idea',fragment);i.update(statement=statement,status=status,related_element_ids=[x['id'] for x in elements],alternative_group_id=None,selected_parts=[statement] if status=='accepted' else [],decision_ids=[],resulting_assertion_ids=[]);return self.add(i)
 def after(self):
  s=copy.deepcopy(self.before);s.update({r['id']:r for r in self.rs});return s
 def checkpoint_summary(self,introduction,requested=False,extra=None):
  s=self.after();project=next(r for r in s.values() if r['kind']=='novel_project');summary=records.checkpoint_summary(project,s,requested=requested);assert summary['required']
  lines=[introduction,'',f'Checkpoint summary: exchange {self.p["exchange_id"]}, sequence {self.p["sequence"]}; predecessor Git checkpoint {self.p["expected_git_head"]} (sequence {self.history[-1]["sequence"]}). References identify the supporting record revisions.']
  if extra:lines.extend(['',extra])
  lines.extend(['','Established decisions:',''])
  for r in s.values():
   if r['kind']=='idea' and r['status']=='accepted':
    ds=', '.join(cite(s[x]) for x in r['decision_ids']);lines.append('- '+r['statement']+' ('+cite(r)+'; decision '+ds+').')
  lines.extend(['','Proposed or unresolved; none of these is accepted:',''])
  for r in s.values():
   if r['kind']=='idea' and r['status'] in ('proposed','unresolved'):
    label='unresolved alternative' if r['alternative_group_id'] else r['status'];lines.append('- '+r['statement']+' ('+cite(r)+'; '+label+').')
  lines.extend(['','Open and unanswered questions:',''])
  for q in summary['open_questions']:lines.append('- '+q['text']+' ('+cite(q)+').')
  lines.extend(['','Paused here until your next direction.'])
  (e/(self.case+'-summary.json')).write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
  return '\n'.join(lines)
 def finish(self,reply,review):
  self.p['messages'][1]['text']=reply;self.p['continuity_review']=review;self.p['payload_digest']=records.digest(self.p)
  assert self.p['messages'][0]['text']==self.capture['data']['text'] and self.p['input_artifacts'][0]==self.capture['data']['input_artifact']
  (e/(self.case+'-payload.json')).write_text(json.dumps(self.p,ensure_ascii=False,indent=2),encoding='utf-8');(e/(self.case+'-response.txt')).write_text(reply,encoding='utf-8')
  print(json.dumps({'exchange_id':self.p['exchange_id'],'session_id':self.p['session_id'],'record_count':len(self.rs),'expected_head':self.p['expected_git_head']},separators=(',',':')))
